const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const locations={dunwold:{name:'Dunwold',type:'city',area:'Lower Ward',description:'The city stirs beneath the bell tower',weather:'Grey morning · mist lifting',scene:'Market lane · north-east'},market:{name:'Dunwold Market',type:'market',area:'Market Square',description:'Canvas awnings stir in the morning wind',weather:'Grey morning · market waking',scene:'Market square · east'},tavern:{name:'The Gilded Stag',type:'tavern',area:'Lower Ward',description:'Lamplight pools beneath a carved stag',weather:'Warm hearth · smoke curling',scene:'The Gilded Stag · south lane'},guild:{name:'The Wayfarers’ Hall',type:'guild',area:'Old Quarter',description:'A brass compass hangs above the heavy oak door',weather:'Rain threatening · wind from the west',scene:'Old Quarter · guild row'},bank:{name:'Dunwold Counting House',type:'bank',area:'Crown Ward',description:'Iron shutters guard the Counting House',weather:'Clouded noon · bells distant',scene:'Crown Ward · east street'},docks:{name:'The Salt Quay',type:'docks',area:'Riverside',description:'The river carries a smell of tar and faraway storms',weather:'River fog · gulls crying',scene:'Salt Quay · riverside'},village:{name:'Briar Glen',type:'village',area:'South road',description:'Smoke rises from low cottages and a lonely mill',weather:'Pale sun · wind in the wheat',scene:'Briar Glen · village green'},forest:{name:'Hollowpine Forest',type:'forest',area:'Old north road',description:'Pine boughs crowd the narrow track; something watches',weather:'Cold shade · birds gone quiet',scene:'Hollowpine track · deep wood'},camp:{name:'Bandit Hollow',type:'camp',area:'Hollowpine Forest',description:'A stolen banner hangs over the bandit camp',weather:'Low cloud · smoke from the hollow',scene:'Bandit Hollow · ravine camp'},manor:{name:'The Thornmere Estate',type:'manor',area:'High Ward',description:'A walled estate watches over the city',weather:'Dusk light · watch fires lit',scene:'High Ward · Thornmere wall'}};
const mapCells=[['forest','','camp','','village'],['','','forest','',''],['docks','','dunwold','market','manor'],['','','tavern','guild','bank'],['','','','', '']];
const initial={name:'Mara Vey',level:3,xp:240,gold:146,health:82,maxHealth:100,mana:48,maxMana:60,stamina:76,maxStamina:90,day:12,hour:6,minute:40,location:'dunwold',steps:0,facing:0,rep:8,wanted:0,trust:{'Elian Voss':28,'Tamsin Reed':52,'Ser Joryn':8,'Pella':34,'Merrit':12,'Nessa':19},bank:90,skills:{blade:1,shadow:0,mercy:0,wayfarer:0},attributes:{health:0,mana:0,stamina:0},inventory:[{name:'Weathered arming sword',type:'weapon',desc:'A plain blade, honest and well-balanced.',value:22,equipped:true},{name:'Ashwood buckler',type:'armor',desc:'Light enough for a quick retreat.',value:16,equipped:true},{name:'Moth-eaten road cloak',type:'armor',desc:'Better for weather than arrows.',value:8,equipped:true},{name:'Copper ring of the ford',type:'accessory',desc:'A keepsake; faintly warm at dawn.',value:18,equipped:true},{name:'Waybread',type:'food',desc:'Restores 18 vigor.',value:3,count:3},{name:'Small beer',type:'drink',desc:'Restores 12 vigor; a second will make the room sway.',value:2,count:2},{name:'Silver locket',type:'stolen',desc:'Initials scratched away. A fence might know its worth.',value:35,count:1}],quests:[{title:'A Quiet Disappearance',text:'Tamsin Reed has not seen her brother since last market day. Ask around the lower ward.',progress:'Speak with Tamsin',reward:'85 crowns · 120 XP',done:false},{title:'Ashes in the Pines',text:'Something has been burning charcoal beyond the north road. The guild will pay for answers.',progress:'Find the Hollowpine camp',reward:'110 crowns · 180 XP',done:false}],flags:{},combat:null,log:[]};
let game=loadAuto()||structuredClone(initial), modalTab='';
function loadAuto(){try{const x=localStorage.getItem('ashenmere-auto');return x?JSON.parse(x):null}catch{return null}}
function saveAuto(){localStorage.setItem('ashenmere-auto',JSON.stringify(game))}
function addLog(text){game.log.unshift({time:timeText(),text});game.log=game.log.slice(0,5);renderLog();saveAuto()}
function timeText(){return `${String(game.hour).padStart(2,'0')}:${String(game.minute).padStart(2,'0')}`}
function advance(min=10){let total=game.hour*60+game.minute+min;game.day+=Math.floor(total/1440);total%=1440;game.hour=Math.floor(total/60);game.minute=total%60;renderClock()}
function renderClock(){$('#clock').innerHTML=`${timeText()}<small>Frostwane · Day ${game.day}</small>`}
function render(){renderClock();$('#place-label').textContent=locations[game.location]?.name||'Dunwold';$('#scene-title').textContent=`${(locations[game.location]?.name||'DUNWOLD').toUpperCase()} · ${(locations[game.location]?.area||'').toUpperCase()}`;$('#scene-caption').innerHTML=`${locations[game.location]?.description||''}<small>${locations[game.location]?.scene||''}</small>`;$('#weather').textContent=locations[game.location]?.weather||'Low clouds · wind turning';$('#scene-art').className='scene-art '+(game.location==='forest'||game.location==='camp'?'forest':game.location==='tavern'?'tavern':'');$('#gold-count').textContent=game.gold.toLocaleString();meter('health',game.health,game.maxHealth);meter('mana',game.mana,game.maxMana);meter('stamina',game.stamina,game.maxStamina);$('#character-name').textContent=game.name;$('#level').textContent=game.level;$('#xp-label').textContent=`${game.xp} / ${game.level*200} XP`;$('#xp-fill').style.width=`${Math.min(100,game.xp/(game.level*200)*100)}%`;$('#rep-pill').textContent=game.wanted>0?`Wanted · ${game.wanted}¢`:game.rep>=50?'Well regarded':game.rep<0?'Distrusted':'Known face';$('#rep-pill').style.color=game.wanted?'#e19482':game.rep>=50?'#a9c28e':'';renderMap();renderLog();renderQuests();renderNpcs();}
function meter(id,v,max){$(`#${id}-fill`).style.width=`${Math.max(0,v/max*100)}%`;$(`#${id}-value`).textContent=`${v}/${max}`}
function renderMap(){let html='';mapCells.flat().forEach((id,i)=>{const cls=['map-cell',id===game.location?'current':'',id&&id!==game.location?'poi':'',id==='forest'||id==='camp'?'forest-cell':''].join(' ');html+=`<button class="${cls}" title="${id?locations[id].name:'Uncharted'}" data-dest="${id}">${id===game.location?'◆':id?'◇':'·'}</button>`});$('#map-grid').innerHTML=html;$$('[data-dest]').forEach(b=>b.onclick=()=>b.dataset.dest&&travel(b.dataset.dest))}
function renderLog(){const logs=game.log.length?game.log:[{time:timeText(),text:'You arrive in Dunwold with a little coin, an old sword, and more questions than answers.'}];$('#log-list').innerHTML=logs.slice(0,4).map(l=>`<div class="log-entry"><span class="log-time">${l.time}</span><span>${l.text}</span></div>`).join('')}
function renderQuests(){$('#quest-list').innerHTML=game.quests.filter(q=>!q.done).slice(0,2).map(q=>`<div class="quest-card"><h3>${q.title}</h3><p>${q.text}</p><div class="quest-meta"><span>${q.progress}</span><span>${q.reward}</span></div></div>`).join('')||'<div style="color:#929783;font-size:10px">No open work. Perhaps the board has something.</div>'}
const npcData=[{name:'Elian Voss',role:'Guild factor',home:'guild',work:'guild',shop:'market',tavern:'tavern',sleep:23,wake:7,icon:'✦'},{name:'Tamsin Reed',role:'Herbalist · searching for kin',home:'market',work:'market',shop:'dunwold',tavern:'tavern',sleep:22,wake:6,icon:'❧'},{name:'Ser Joryn',role:'City watch',home:'dunwold',work:'manor',shop:'dunwold',tavern:'tavern',sleep:1,wake:8,icon:'♜'},{name:'Pella',role:'Innkeeper at the Gilded Stag',home:'tavern',work:'tavern',shop:'market',tavern:'tavern',sleep:2,wake:9,icon:'♨'},{name:'Merrit',role:'Dockhand · knows the quay',home:'docks',work:'docks',shop:'market',tavern:'tavern',sleep:21,wake:5,icon:'⚓'},{name:'Nessa',role:'Caravan guard · north road',home:'village',work:'forest',shop:'market',tavern:'tavern',sleep:22,wake:6,icon:'⚔'}];
function npcPlace(n){let h=game.hour;if(h<n.wake||h>=n.sleep)return n.home;if(h>=18&&h<22)return n.tavern;if(h>=12&&h<14)return n.shop;return n.work}
function renderNpcs(){let present=npcData.filter(n=>npcPlace(n)===game.location).slice(0,3);if(!present.length)present=npcData.filter(n=>n.home===game.location||n.work===game.location).slice(0,3);$('#npc-list').innerHTML=present.map(n=>{let trust=game.trust[n.name]||0;return `<div class="npc-row"><div class="npc-face">${n.icon}</div><div><div class="npc-name">${n.name}</div><div class="npc-role">${n.role}</div></div><div class="npc-trust">${trust}<div class="trust-track"><div class="trust-fill" style="width:${Math.max(0,trust)}%"></div></div></div></div>`}).join('')||'<div style="color:#929783;font-size:10px;padding:8px 0">The street is quiet at this hour.</div>'}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2100)}
function travel(dest){if(dest===game.location){toast('You are already here.');return}if(dest==='camp'&&!game.flags.campFound){game.flags.campFound=true;const q=game.quests.find(q=>q.title==='Ashes in the Pines');if(q)q.progress='Explore the bandit hollow'}game.location=dest;advance(dest==='forest'||dest==='village'?55:20);game.stamina=Math.max(0,game.stamina-(dest==='forest'?8:3));addLog(`You take the road to <strong>${locations[dest].name}</strong>. The journey costs a little time and vigor.`);render();if(dest==='camp'&&!game.flags.campCleared)beginCombat('A bandit lookout steps into the path, one hand on a notched blade.');}
function move(dir){if(game.combat){toast('Choose your next move in the encounter.');return}if(dir==='left'||dir==='right'){game.facing=(game.facing+(dir==='left'?3:1))%4;advance(2);game.steps++;$('#scene-caption').innerHTML=`${locations[game.location].description}<small>${['north','east','south','west'][game.facing]} · ${locations[game.location].scene.split('·')[0]}</small>`;renderClock();return}const nearby={dunwold:['market','tavern','guild','bank','docks'],market:['dunwold','tavern','guild'],tavern:['dunwold','market','guild'],guild:['dunwold','market','bank'],bank:['dunwold','guild','manor'],docks:['dunwold','village'],village:['docks','forest'],forest:['village','camp'],camp:['forest'],manor:['bank','dunwold']};const paths=nearby[game.location]||[];if(paths.length){let idx=game.steps%paths.length;let target=paths[idx];game.steps++;if(game.steps%3===0)travel(target);else{advance(3);game.stamina=Math.max(0,game.stamina-1);addLog('You walk a few paces, keeping to the edge of the street.');render()}}}
function openModal(title,eyebrow,intro,body,wide=false){$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML=`<div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p class="modal-intro">${intro}</p>${body}`;$('#modal-backdrop').classList.add('open')}
function closeModal(){$('#modal-backdrop').classList.remove('open')}
function menu(){openModal('Pause & preserve','The long road','Five ledgers, five lives. Your progress also autosaves in this browser.',`<div class="modal-grid"><div class="modal-card"><h3>Save game</h3><p>Keep this character safe in one of five local save slots.</p><div class="modal-actions"><button class="gold-btn" data-ui="saves">Choose a slot</button></div></div><div class="modal-card"><h3>Load game</h3><p>Return to a saved journey. Unsaved changes will be lost.</p><div class="modal-actions"><button class="plain-btn" data-ui="loads">Browse ledgers</button></div></div><div class="modal-card"><h3>Character & talents</h3><p>Review your abilities and choose how to grow.</p><div class="modal-actions"><button class="plain-btn" data-ui="skills">Open talents</button></div></div><div class="modal-card"><h3>Leave the road</h3><p>Close this chapter. The game remains saved in this browser.</p><div class="modal-actions"><button class="danger-btn" data-ui="exit">Exit to title</button></div></div></div>`)}
function slots(mode){let arr=[];for(let i=1;i<=5;i++){let data=null;try{data=JSON.parse(localStorage.getItem('ashenmere-slot-'+i))}catch{};arr.push(`<div class="slot-row"><div class="slot-no">0${i}</div><div class="slot-details">${data?`${data.name} · Level ${data.level}<small>${locations[data.location]?.name||'Unknown'} · Day ${data.day} · ${data.gold} crowns</small>`:'Empty ledger'}${!data?'<small>No journey recorded</small>':''}</div><button class="${mode==='save'?'gold-btn':'plain-btn'}" data-slot="${i}" data-mode="${mode}" ${!data&&mode==='load'?'disabled':''}>${mode==='save'?'Save here':'Load'}</button></div>`)}openModal(mode==='save'?'Choose a save slot':'Load a journey','Five ledgers',mode==='save'?'This slot is stored locally in your browser.':'Select a character to continue.',arr.join(''))}
function openSkills(){let options=[['blade','Blade craft','A cleaner strike. +3 damage per rank.'],['shadow','Quiet hands','Better odds when taking what is not yours.'],['mercy','Silver tongue','Bribes cost less; trust comes easier.'],['wayfarer','Roadwise','Reduce travel fatigue; find better provisions.']];let body=`<div class="notice">Unspent talent points: <strong>${game.talentPoints||0}</strong> · Earn a point at each new level.</div><div class="modal-grid" style="margin-top:12px">${options.map(([id,n,d])=>`<div class="modal-card"><h3>${n} · Rank ${game.skills[id]||0}</h3><p>${d}</p><button class="${(game.talentPoints||0)>0?'gold-btn':'plain-btn'}" data-skill="${id}" ${(game.talentPoints||0)<=0?'disabled':''}>Improve</button></div>`).join('')}</div><div class="section-label" style="margin:20px 0 8px">Choose an attribute · one point each level</div><div class="modal-actions"><button class="plain-btn" data-attribute="health">+ Vitality</button><button class="plain-btn" data-attribute="mana">+ Mana</button><button class="plain-btn" data-attribute="stamina">+ Vigor</button></div>`;openModal('The making of a wanderer','Talents & attributes',`Level ${game.level} · experience shapes the body, but the road shapes the rest.`,body,true)}
function openInventory(){let items=game.inventory.filter(i=>i.count===undefined||i.count>0);let body=`<div class="item-list">${items.map((it,i)=>`<div class="item"><div class="item-icon">${it.type==='weapon'?'⚔':it.type==='armor'?'⬡':it.type==='food'?'◒':it.type==='drink'?'♜':it.type==='stolen'?'◇':'✧'}</div><div><div class="item-name">${it.name}${it.count>1?` ×${it.count}`:''}${it.equipped?' · equipped':''}</div><div class="item-desc">${it.desc}</div></div><span class="item-value">${it.value}¢</span>${it.type==='food'||it.type==='drink'?`<button class="plain-btn" data-consume="${game.inventory.indexOf(it)}">Use</button>`:it.type==='weapon'||it.type==='armor'||it.type==='accessory'?`<button class="plain-btn" data-equip="${game.inventory.indexOf(it)}">${it.equipped?'Unequip':'Equip'}</button>`:''}</div>`).join('')}</div><div class="notice">Carried crowns: ${game.gold} · Bank: ${game.bank} crowns</div>`;openModal('What you carry','Inventory · equipment',`A practical kit for the uncertain miles ahead.`,body,true)}
function journal(){let body=`<div class="tab-row"><button class="tab active">Quests</button><button class="tab" data-ui="reputation">Standing</button><button class="tab" data-ui="map">Road map</button></div>${game.quests.map(q=>`<div class="modal-card" style="margin-bottom:8px;opacity:${q.done?.65:1}"><h3>${q.title} ${q.done?'· Complete':''}</h3><p>${q.text}</p><div class="quest-meta"><span>${q.done?'Completed':q.progress}</span><span>${q.reward}</span></div></div>`).join('')}`;openModal('Notes from the road','Journal',`Names, promises, and places that may matter.`,body)}
function reputation(){let body=`<div class="modal-grid"><div class="modal-card"><h3>Dunwold · ${game.rep>=50?'Well regarded':game.rep<0?'Distrusted':'Known face'}</h3><p>Standing: ${game.rep} / 100. Helping townsfolk earns trust; theft and violence bring watchful eyes.</p><div class="quest-meta"><span>Wanted bounty</span><strong>${game.wanted} crowns</strong></div></div><div class="modal-card"><h3>Town watch</h3><p>${game.wanted>0?'The watch has your description. Keep your hood up, or settle your debt.':'No active bounty. The watch has little reason to trouble you.'}</p><button class="${game.wanted?'gold-btn':'plain-btn'}" data-ui="wanted">${game.wanted?'Pay bounty':'No bounty owed'}</button></div></div>`;openModal('A name in each town','Reputation & bounty','Your actions travel faster than you do.',body)}
function people(){let body=npcData.map(n=>`<div class="npc-row"><div class="npc-face">${n.icon}</div><div><div class="npc-name">${n.name}</div><div class="npc-role">${npcPlace(n)===game.location?'Here now':`Usually found: ${locations[npcPlace(n)]?.name||n.role}`}</div></div><div class="npc-trust">${game.trust[n.name]||0}<div class="trust-track"><div class="trust-fill" style="width:${Math.max(0,game.trust[n.name]||0)}%"></div></div></div><button class="plain-btn" data-person="${n.name}">Speak</button></div>`).join('');openModal('People of the road','A living town',`Most people keep to their own hours. Find them where their work, errands, or habits take them.`,body,true)}
function townAction(panel){if(panel==='inventory')return openInventory();if(panel==='skills'||panel==='character')return openSkills();if(panel==='journal')return journal();if(panel==='people')return people();if(panel==='map'){let body=`<div class="modal-grid">${Object.entries(locations).map(([id,l])=>`<div class="modal-card"><h3>${l.name}</h3><p>${l.description}</p><button class="plain-btn" data-travel="${id}">Travel there</button></div>`).join('')}</div>`;return openModal('Roads & places','Known world',`The realm is larger than these old maps admit. Roads between places take time.`,body,true)}if(panel==='guild')return guildPanel();if(panel==='bank')return bankPanel();if(panel==='board')return boardPanel()}
function speak(name){let n=npcData.find(x=>x.name===name);if(!n)return;let trust=game.trust[name]||0;let body=`<div class="notice">Trust with ${name}: <strong>${trust}/100</strong>. Trust grows through honest help; threats may earn compliance, not loyalty.</div><div class="modal-grid" style="margin-top:12px"><div class="modal-card"><h3>Build a relationship</h3><p>Spend time over a warm drink. A small kindness may be remembered.</p><button class="plain-btn" data-social="kind" data-name="${name}">Share a drink · 4 crowns</button></div><div class="modal-card"><h3>Offer a bribe</h3><p>Money can loosen a tongue when goodwill cannot.</p><button class="gold-btn" data-social="bribe" data-name="${name}">Offer 20 crowns</button></div><div class="modal-card"><h3>Threaten</h3><p>Make demands. It may work, but the whole street will hear.</p><button class="danger-btn" data-social="threat" data-name="${name}">Lean on them</button></div><div class="modal-card"><h3>Ask about Tamsin's brother</h3><p>Most people have heard something. Trust helps turn rumor into fact.</p><button class="plain-btn" data-social="clue" data-name="${name}">Ask around</button></div></div>`;openModal(name,'Trust & conversation',`${n.role}. ${npcPlace(n)===game.location?'They are here now.':'You catch up with them on the road.'}`,body)}

function guildPanel(){let body=`<div class="modal-grid"><div class="modal-card"><h3>Wayfarers’ Hall</h3><p>Caravan guards, lost couriers, and jobs too small for the crown. The hall asks no questions it cannot afford to answer.</p><div class="modal-actions"><button class="gold-btn" data-ui="guild-join">Sign the ledger</button><button class="plain-btn" data-ui="guild-jobs">Ask for work</button></div></div><div class="modal-card"><h3>Ashes in the Pines</h3><p>Investigate the charcoal fires and the missing supply cart. Take proof back to the factor.</p><div class="modal-actions"><button class="plain-btn" data-travel="forest">Take the north road</button></div></div></div>`;openModal('The Wayfarers’ Hall','Guilds & contracts','A modest guild, but its routes touch every town worth finding.',body)}
function boardPanel(){let body=`<div class="modal-grid"><div class="modal-card"><h3>A Quiet Disappearance</h3><p>Tamsin Reed is looking for her brother, Harl. Last seen by the market weigh-house.</p><div class="modal-actions"><button class="plain-btn" data-social="clue" data-name="Tamsin Reed">Ask Tamsin</button><button class="plain-btn" data-travel="market">Visit the market</button></div></div><div class="modal-card"><h3>Charcoal & trouble</h3><p>A merchant pays for news of bandits on the north road. Proof is worth more than a story.</p><div class="modal-actions"><button class="plain-btn" data-travel="forest">Scout Hollowpine</button></div></div><div class="modal-card"><h3>Honest work</h3><p>Haul a sack at the docks, run a message, or spend a day keeping the guild's road clear.</p><button class="gold-btn" data-ui="guild-jobs">Take a small contract</button></div></div>`;openModal('The notice board','Work & rumors','The ink runs in the rain. Someone has pinned up fresh work.',body)}
function bankPanel(){let body=`<div class="notice">On deposit: <strong>${game.bank} crowns</strong> · In your purse: <strong>${game.gold} crowns</strong></div><div class="modal-grid" style="margin-top:12px"><div class="modal-card"><h3>Deposit</h3><p>Put away 25 crowns. The Counting House keeps careful ledgers.</p><button class="gold-btn" data-bank="deposit">Deposit 25</button></div><div class="modal-card"><h3>Withdraw</h3><p>Take 25 crowns from your account.</p><button class="plain-btn" data-bank="withdraw">Withdraw 25</button></div><div class="modal-card"><h3>The vault</h3><p>There is a second way into the vault: a small vent behind the ledger shelves. A risky gamble against iron, locks, and the watch.</p><button class="danger-btn" data-bank="vault">Try the vault</button></div><div class="modal-card"><h3>Wanted in Dunwold?</h3><p>Any stolen coin may be more trouble than it is worth. The watch patrols the Crown Ward after dark.</p><div class="quest-meta"><span>Current bounty</span><strong>${game.wanted} crowns</strong></div></div></div>`;openModal('The Counting House','Bank & vault',`Your account holds ${game.bank} crowns. The teller's keys hang at her belt.`,body)}
function tavernPanel(){let body=`<div class="modal-grid"><div class="modal-card"><h3>A mug & a meal</h3><p>Pella keeps a warm room, hot broth, and small beer. A second round makes the night pleasantly uncertain.</p><button class="gold-btn" data-tavern="meal">Broth & bread · 6 crowns</button><button class="plain-btn" data-tavern="drink">Small beer · 3 crowns</button></div><div class="modal-card"><h3>Dice at the back table</h3><p>A few regulars play bones for low stakes. They are friendly until the third cup.</p><button class="plain-btn" data-tavern="dice">Play a hand · 10 crowns</button></div><div class="modal-card"><h3>A quiet room</h3><p>A clean bed, a bolted door, and six hours of sleep for 12 crowns. No questions asked.</p><button class="plain-btn" data-tavern="sleep">Rent a room · 12 crowns</button></div><div class="modal-card"><h3>The Amber Room</h3><p>A discreet salon upstairs offers the company of adult courtesans: conversation, music, and companionship by mutual choice. Nothing is owed beyond the agreed price; the rest of the night is left private.</p><button class="plain-btn" data-tavern="salon">Spend the evening · 18 crowns</button></div></div>`;openModal('The Gilded Stag','Tavern · Dunwold',`Pella wipes a cup with a clean rag. “The fire's warm, traveler. What'll it be?”`,body)}
function fencePanel(){let stolen=game.inventory.filter(i=>i.type==='stolen'&&(i.count||0)>0);let body=stolen.length?`<div class="item-list">${stolen.map(it=>`<div class="item"><div class="item-icon">◇</div><div><div class="item-name">${it.name}</div><div class="item-desc">${it.desc}</div></div><span class="item-value">offers ${Math.floor(it.value*.65)}¢</span><button class="gold-btn" data-fence="${game.inventory.indexOf(it)}">Sell</button></div>`).join('')}</div>`:'<div class="notice">Nothing hot to move. Come back with something taken from a rich pocket or a locked room.</div>';body+=`<div class="modal-card" style="margin-top:10px"><h3>Quiet exchanges</h3><p>They meet behind the tannery after dusk. No names; no questions. The city watch gets a cut either way.</p></div>`;openModal('The back-room fence','Stolen goods',`A narrow door opens onto a room smelling of wet leather. The fence looks over your shoulder before speaking.`,body)}
function dicePanel(){openModal('Bones on the table','A tavern game',`Pella pours a thimble of ale. “Two dice. Beat my sum and you take the pot. Lose and the coin stays here.”`,`<div class="modal-card" style="text-align:center"><p>Ante: 10 crowns · Your odds are as fair as the house can make them.</p><button class="gold-btn" data-dice="roll">Roll the bones</button><div class="dice-result" id="dice-result">⚄ &nbsp; ⚁</div><div id="dice-note" style="color:#999d88;font-size:10px">Waiting on your throw.</div></div>`)}
function beginCombat(text){game.combat={enemy:'Bandit lookout',hp:30,max:30};openCombat(text)}
