function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function changeTrust(name,n){game.trust[name]=Math.max(-100,Math.min(100,(game.trust[name]||0)+n))}
function itemCount(name){return game.inventory.filter(i=>i.name===name).reduce((a,i)=>a+(i.count||1),0)}
function takeItem(name,n=1){let i=game.inventory.find(x=>x.name===name&&(x.count||1)>=n);if(!i)return false;if(i.count){i.count-=n;if(i.count<=0)game.inventory.splice(game.inventory.indexOf(i),1)}else game.inventory.splice(game.inventory.indexOf(i),1);return true}
function giveItem(item){let old=game.inventory.find(i=>i.name===item.name);if(old&&old.count)old.count+=item.count||1;else game.inventory.push({...item})}
function awardXP(n){game.xp+=n;while(game.xp>=game.level*200){game.xp-=game.level*200;game.level++;game.maxHealth+=8;game.maxMana+=5;game.maxStamina+=6;game.health=game.maxHealth;game.mana=game.maxMana;game.stamina=game.maxStamina;toast(`Level ${game.level}! Choose a talent from your character page.`);game.flags.talentPoints=(game.flags.talentPoints||0)+1}}
function nearby(){let a=npcData.filter(n=>npcPlace(n)===game.location);return a.length?a:npcData.filter(n=>n.home===game.location||n.work===game.location)}
function finishQuest(title,reward,xp,rep=3){let q=game.quests.find(x=>x.title===title);if(!q||q.done)return false;q.done=true;game.gold+=reward;game.rep+=rep;awardXP(xp);addLog(`<strong>${esc(title)}</strong> is complete. You receive ${reward} crowns and ${xp} experience.`);render();return true}
function renderInventory(){let rows=game.inventory.map((i,n)=>`<div class="choice-row"><div><b>${esc(i.name)}${i.count>1?` ×${i.count}`:''}</b><small>${esc(i.desc)} · ${i.equipped?'Equipped':'Value '+i.value+' crowns'}</small></div><button class="choice-btn" data-do="${i.type==='food'||i.type==='drink'?'consume':i.equipped?'unequip':'equip'}" data-index="${n}">${i.type==='food'||i.type==='drink'?'Use':i.equipped?'Unequip':'Equip'}</button></div>`).join('');openModal('Your effects','PACK & EQUIPMENT','Everything you have carried this far.',`${rows||'<p>Your pack is empty.</p>'}<p class="modal-note">Selling and fencing are available at the market and docks.</p>`,true)}
function openMenu(){let slots=Array.from({length:5},(_,i)=>{let d=null;try{d=JSON.parse(localStorage.getItem(`ashenmere-slot-${i+1}`))}catch{}return `<div class="choice-row"><div><b>Save ${i+1}${d?' · '+esc(d.name||'Mara Vey'):''}</b><small>${d?`${esc(locations[d.location]?.name||d.location)} · Day ${d.day} · Level ${d.level}`:'Empty slot'}</small></div><span><button class="choice-btn" data-do="save" data-slot="${i+1}">Save</button> <button class="choice-btn" data-do="load" data-slot="${i+1}" ${d?'':'disabled'}>Load</button></span></div>`}).join('');openModal('The road remembers','PAUSE & SAVE','Five local save slots are kept on this device. Autosave is always active.',`${slots}<div class="modal-actions"><button class="choice-btn" data-do="close">Return to the road</button><button class="choice-btn danger" data-do="exit">Leave the road</button></div>`,true)}
function listChoices(title,eyebrow,intro,choices){openModal(title,eyebrow,intro,choices.map(c=>`<div class="choice-row"><div><b>${c.label}</b><small>${c.note||''}</small></div><button class="choice-btn" data-do="${c.do}" ${c.disabled?'disabled':''}>${c.button||'Choose'}</button></div>`).join('')||'<p>No opportunities here just now.</p>',true)}
function personPanel(){let ns=npcData.map(n=>{let t=game.trust[n.name]||0;return `<div class="choice-row"><div><b>${n.icon} ${esc(n.name)}</b><small>${esc(n.role)} · usually found at ${esc(locations[npcPlace(n)]?.name||n.home)}</small></div><span class="npc-trust">Trust ${t}</span></div>`}).join('');openModal('People of the road','NAMES & FACES','Schedules shift with the hour. A familiar face may be elsewhere tomorrow.',ns,true)}
function journalPanel(){let qs=game.quests.map(q=>`<div class="choice-row"><div><b>${esc(q.title)} ${q.done?'· Complete':''}</b><small>${esc(q.text)}<br>${esc(q.done?'Resolved':q.progress)} · Reward: ${esc(q.reward)}</small></div></div>`).join('');openModal('The journal','QUESTS & REPUTATION',`Standing: ${game.rep} · Bounty: ${game.wanted} crowns.`,`${qs}<div class="choice-row"><div><b>Recent chronicle</b><small>${game.log.map(l=>`${esc(l.time)} — ${l.text}`).join('<br>')||'The road is quiet.'}</small></div></div>`,true)}
function showMap(){let names=Object.entries(locations).map(([id,l])=>`<button class="choice-btn" data-do="travel" data-dest="${id}" ${id===game.location?'disabled':''}>${esc(l.name)}${id===game.location?' · Here':''}</button>`).join(' ');openModal('Known roads','THE LANDS OF ASHENMERE','Travel costs time and vigor. The north road is not safe.',`<div class="map-choices">${names}</div>`,true)}
function guildPanel(){if(game.location!=='guild'&&game.location!=='dunwold')return toast('The Wayfarers’ Hall is in Dunwold’s Old Quarter.');listChoices('Wayfarers’ Hall','GUILD SERVICES','Elian keeps a fair ledger, and remembers those who keep their word.',[{label:'Register with the Wayfarers',note:'A small fee, useful work, and a name in the ledger.',button:'Pay 10 crowns',do:'register',disabled:game.gold<10||game.flags.registered},{label:'Ask Elian about the missing Reed',note:'Trust and a patient question may uncover a lead.',button:'Ask',do:'elian'}])}
function boardPanel(){let open=game.quests.filter(q=>!q.done);listChoices('Work for the road','QUEST BOARD','The board is crowded with rain-softened notices.',open.map(q=>({label:q.title,note:q.text+' Current lead: '+q.progress,button:'Track',do:'track'})).concat([{label:'A rat-haunted cellar',note:'Clear the cellar beneath the market; 40 crowns and 60 XP.',button:game.flags.cellar?'Taken':'Accept',do:'cellar',disabled:!!game.flags.cellar}]))}
function bankPanel(){if(game.location!=='bank')return toast('The Counting House stands in the Crown Ward.');listChoices('Dunwold Counting House','SECURE YOUR COIN',`Balance: ${game.bank} crowns. The teller watches your hands.`,[{label:'Deposit 25 crowns',note:'Secure money cannot be lost while travelling.',button:'Deposit',do:'deposit',disabled:game.gold<25},{label:'Withdraw 25 crowns',note:'Take coin from your account.',button:'Withdraw',do:'withdraw',disabled:game.bank<25},{label:'Try the vault after closing',note:'High risk. A serious crime brings a bounty and the watch.',button:'Attempt theft',do:'vault',disabled:game.hour>=8&&game.hour<18}])}
function actEat(){let food=game.inventory.find(i=>i.type==='food'),drink=game.inventory.find(i=>i.type==='drink');listChoices('A moment’s respite','FOOD & DRINK','Travel is easier with a full belly.',[{label:food?.name||'No food',note:food?.desc||'Visit the market for provisions.',button:'Eat',do:'eatfood',disabled:!food},{label:drink?.name||'No drink',note:drink?.desc||'Visit the tavern or market.',button:'Drink',do:'drink',disabled:!drink}])}
function actSleep(){if(!['tavern','village','dunwold','docks'].includes(game.location))return toast('There is no safe bed here. Try the Gilded Stag or Briar Glen.');openModal('Find a bed','REST & RECOVERY','A few hours of safety restore body and spirit. A room costs 8 crowns.',`<div class="choice-row"><div><b>Sleep until morning</b><small>Restores health, mana, and vigor. Advances time to 06:00.</small></div><button class="choice-btn" data-do="sleepnow" ${game.gold<8?'disabled':''}>Pay 8 crowns</button></div>`)}
function talkPanel(){let ns=nearby();if(!ns.length)return toast('No one is close enough to talk to.');listChoices('A word with a passerby','CONVERSATION','Listen first. Trust is earned, not owed.',ns.map(n=>({label:n.icon+' '+n.name,note:n.role+' · Trust '+(game.trust[n.name]||0),button:'Speak',do:'speak',name:n.name})).map(c=>({...c,button:`Speak`})))}
function beginCombat(desc){if(game.combat)return;game.combat={enemy:desc.includes('rat')?'Cellar rat':'Bandit lookout',hp:desc.includes('rat')?24:38,max:desc.includes('rat')?24:38,desc,round:0};renderCombat()}
function renderCombat(){if(!game.combat)return;let c=game.combat;openModal(c.enemy,'DANGER ON THE ROAD',c.desc,`<div class="combat-card"><b>${esc(c.enemy)}</b><div class="trust-track"><div class="trust-fill" style="width:${100*c.hp/c.max}%"></div></div><small>Enemy vitality ${c.hp}/${c.max}</small></div><div class="modal-actions"><button class="choice-btn" data-do="attack">Strike</button><button class="choice-btn" data-do="spell" ${game.mana<10?'disabled':''}>Cast ember (10 mana)</button><button class="choice-btn" data-do="flee">Retreat</button></div>`,true)}
function combatTurn(action){let c=game.combat;if(!c)return;if(action==='flee'){game.combat=null;game.location=c.enemy==='Bandit lookout'?'forest':game.location;advance(15);addLog('You retreat from danger, shaken but alive.');render();return}let damage=action==='spell'?18+Math.floor(Math.random()*8):10+game.skills.blade*3+Math.floor(Math.random()*7);if(action==='spell')game.mana-=10;else game.stamina=Math.max(0,game.stamina-5);c.hp-=damage;if(c.hp<=0){let enemy=c.enemy;game.combat=null;game.health=Math.min(game.maxHealth,game.health+5);game.gold+=enemy==='Bandit lookout'?24:0;game.flags.campCleared=enemy==='Bandit lookout'||game.flags.campCleared;advance(8);addLog(`You defeat the ${enemy.toLowerCase()}.`);if(enemy==='Bandit lookout'){let q=game.quests.find(q=>q.title==='Ashes in the Pines');if(q)q.progress='Report to Elian at the guild';game.rep+=2}else if(game.flags.cellar){finishQuest('A rat-haunted cellar',40,60)}render();return}let hurt=6+Math.floor(Math.random()*8);game.health=Math.max(0,game.health-hurt);c.round++;advance(3);if(game.health<=0){game.health=Math.ceil(game.maxHealth*.35);game.gold=Math.max(0,game.gold-15);game.location='tavern';game.combat=null;addLog('You wake at the Gilded Stag, alive but poorer by 15 crowns.');render();return}renderCombat();render()}
function marketPanel(){listChoices('Market lane','TRADE & FENCING','Merchants buy honest goods; the quay fence asks fewer questions.',[{label:'Buy waybread',note:'Restore vigor · 4 crowns each.',button:'Buy · 4¢',do:'buyfood',disabled:game.gold<4},{label:'Buy small beer',note:'Restore vigor · 3 crowns each.',button:'Buy · 3¢',do:'buydrink',disabled:game.gold<3},{label:'Sell silver locket',note:'Fence offers 22 crowns. Stolen goods may be recognized.',button:'Sell · 22¢',do:'selllocket',disabled:!itemCount('Silver locket')}])}
function bankAction(which){if(which==='deposit'){game.gold-=25;game.bank+=25}else if(which==='withdraw'){game.bank-=25;game.gold+=25}else{let chance=Math.random();if(chance<.58){game.gold+=75;game.rep-=12;game.wanted+=60;game.flags.vaultRobbed=true;game.health=Math.max(1,game.health-12);toast('You escape with 75 crowns. The watch has your description.')}else{game.wanted+=100;game.rep-=18;game.health=Math.max(1,game.health-20);toast('The watch catches you at the vault. You escape empty-handed.');if(game.health<25)beginCombat('A watchman blocks your escape.')}advance(30)}addLog(which==='vault'?'You risk the Counting House vault.':'You update your account at the Counting House.');render();if(which!=='vault')bankPanel()}
function handleDo(b){let d=b.dataset.do,n=b.dataset.name;if(d==='close')closeModal();else if(d==='save'){localStorage.setItem(`ashenmere-slot-${b.dataset.slot}`,JSON.stringify(game));toast(`Saved to slot ${b.dataset.slot}.`);openMenu()}else if(d==='load'){try{let x=JSON.parse(localStorage.getItem(`ashenmere-slot-${b.dataset.slot}`));if(x){game=x;render();closeModal();toast('Journey loaded.')}}catch{toast('That save could not be read.')}}else if(d==='exit'){closeModal();openModal('The road can wait','LEAVE ASHENMERE','Your journey is autosaved. Close this tab when you are ready.',`<button class="choice-btn" data-do="close">Return to the road</button>`)}else if(d==='travel'){closeModal();travel(b.dataset.dest)}else if(d==='consume'||d==='eatfood'||d==='drink'){let i=d==='consume'?game.inventory[+b.dataset.index]:game.inventory.find(x=>x.type===(d==='drink'?'drink':'food'));if(i&&takeItem(i.name)){game.stamina=Math.min(game.maxStamina,game.stamina+(i.type==='food'?18:12));if(i.type==='food')game.health=Math.min(game.maxHealth,game.health+3);advance(5);addLog(`You take a moment for ${i.name.toLowerCase()}.`);render();if(d==='consume')renderInventory();else actEat()}}else if(d==='equip'||d==='unequip'){let i=game.inventory[+b.dataset.index];if(i){i.equipped=d==='equip';render();renderInventory()}}else if(d==='attack'||d==='spell'||d==='flee')combatTurn(d);else if(d==='deposit'||d==='withdraw'||d==='vault')bankAction(d);else if(d==='sleepnow'){game.gold-=8;game.hour=6;game.minute=0;game.day++;game.health=game.maxHealth;game.mana=game.maxMana;game.stamina=game.maxStamina;game.wanted=Math.max(0,game.wanted-10);addLog('You sleep soundly, waking at first light.');render();closeModal()}else if(d==='register'){game.gold-=10;game.flags.registered=true;game.rep+=2;giveItem({name:'Wayfarers’ token',type:'quest',desc:'A brass token marking your guild registration.',value:0,count:1});addLog('You join the Wayfarers’ Hall. Elian welcomes you to the ledger.');render();guildPanel()}else if(d==='elian'){changeTrust('Elian Voss',5);let q=game.quests.find(q=>q.title==='A Quiet Disappearance');if(q&&!q.done){q.progress='Ask Merrit at the Salt Quay';addLog('Elian mentions that Tamsin’s brother was last seen near the quay.')}else if(game.flags.campCleared)finishQuest('Ashes in the Pines',110,180,5);render();guildPanel()}else if(d==='track')toast('Quest tracked in your journal.');else if(d==='cellar'){game.flags.cellar=true;beginCombat('A cellar rat lunges from the dark beneath the market.')}else if(d==='buyfood'||d==='buydrink'){game.gold-=d==='buyfood'?4:3;giveItem({name:d==='buyfood'?'Waybread':'Small beer',type:d==='buyfood'?'food':'drink',desc:d==='buyfood'?'Restores 18 vigor.':'Restores 12 vigor.',value:d==='buyfood'?3:2,count:1});render();marketPanel()}else if(d==='selllocket'){takeItem('Silver locket');game.gold+=22;game.rep-=1;addLog('You fence the silver locket for 22 crowns.');render();marketPanel()}else if(d==='speak'){speakTo(n)} }
function speakTo(name){let t=game.trust[name]||0;let options=[{label:'Ask about their day',note:'A patient conversation earns a little trust.',button:'Listen',do:'chat',name},{label:'Offer a drink',note:'Costs 5 crowns; trust may grow.',button:'Offer · 5¢',do:'offer',name,disabled:game.gold<5},{label:'Pickpocket',note:'A risky attempt. Failure can bring the watch.',button:'Try your luck',do:'pickpocket',name}];if(name==='Tamsin Reed')options.unshift({label:'Ask about her missing brother',note:'The search began in the lower ward.',button:'Ask',do:'tamsin',name});if(name==='Merrit')options.unshift({label:'Ask what he saw by the quay',note:'A useful lead for Tamsin’s search.',button:'Ask',do:'merrit',name});listChoices(name,'CONVERSATION',`${npcData.find(x=>x.name===name)?.role||'Traveler'} · Trust ${t}`,options)}

