 function move(dir){if(game.combat)return toast('Choose your next move in the encounter.');if(dir!=='forward'){game.facing=(game.facing+(dir==='left'?3:1))%4;advance(2);render();return}let links={dunwold:['market','tavern','guild','bank','docks'],market:['dunwold','tavern','guild'],tavern:['dunwold','market','guild'],guild:['dunwold','market','bank'],bank:['dunwold','guild','manor'],docks:['dunwold','village'],village:['docks','forest'],forest:['village','camp'],camp:['forest'],manor:['bank','dunwold']}[game.location]||[];game.steps++;if(links.length&&game.steps%3===0)travel(links[Math.floor(Math.random()*links.length)]);else{advance(3);game.stamina=Math.max(0,game.stamina-1);addLog('You walk a few paces, keeping to the edge of the street.');render()}}
