function speakTo(name){let t=game.trust[name]||0;let options=[{label:'Ask about their day',note:'A patient conversation earns a little trust.',button:'Listen',do:'chat',name},{label:'Offer a drink',note:'Costs 5 crowns; trust may grow.',button:'Offer · 5¢',do:'offer',name,disabled:game.gold<5},{label:'Pickpocket',note:'A risky attempt. Failure can bring the watch.',button:'Try your luck',do:'pickpocket',name}];if(name==='Tamsin Reed')options.unshift({label:'Ask about her missing brother',note:'The search began in the lower ward.',button:'Ask',do:'tamsin',name});if(name==='Merrit')options.unshift({label:'Ask what he saw by the quay',note:'A useful lead for Tamsin’s search.',button:'Ask',do:'merrit',name});listChoices(name,'CONVERSATION',`${npcData.find(x=>x.name===name)?.role||'Traveler'} · Trust ${t}`,options)}
function doAction(a){if(a==='look'){let ns=nearby();advance(3);addLog(ns.length?`You take in the street. ${ns.map(n=>n.name).join(', ')} ${ns.length===1?'is':'are'} nearby.`:'You take in the street, but see no familiar faces.');render()}else if(a==='eat')actEat();else if(a==='sleep')actSleep();else if(a==='talk')talkPanel()}
function actPanel(p){if(p==='character'){let pts=game.flags.talentPoints||0;openModal(game.name,'CHARACTER & TALENTS',`Level ${game.level} Wanderer · ${game.xp} / ${game.level*200} XP · Standing ${game.rep} · Bounty ${game.wanted} crowns.`,`${pts?`<p>You have ${pts} talent point${pts===1?'':'s'} to spend.</p>`:''}<div class="choice-row"><div><b>Bladecraft · rank ${game.skills.blade}</b><small>Improves damage with every strike.</small></div><button class="choice-btn" data-do="talent" data-talent="blade" ${pts?'':'disabled'}>Train</button></div><div class="choice-row"><div><b>Shadowstep · rank ${game.skills.shadow}</b><small>Improves the odds of a clean pickpocket.</small></div><button class="choice-btn" data-do="talent" data-talent="shadow" ${pts?'':'disabled'}>Train</button></div><div class="choice-row"><div><b>Mercy · rank ${game.skills.mercy}</b><small>Good deeds grant more standing.</small></div><button class="choice-btn" data-do="talent" data-talent="mercy" ${pts?'':'disabled'}>Train</button></div><div class="choice-row"><div><b>Wayfarer · rank ${game.skills.wayfarer}</b><small>Travel costs less vigor.</small></div><button class="choice-btn" data-do="talent" data-talent="wayfarer" ${pts?'':'disabled'}>Train</button></div>`,true)}else if(p==='inventory')renderInventory();else if(p==='skills')actPanel('character');else if(p==='journal')journalPanel();else if(p==='people')personPanel();else if(p==='map')showMap();else if(p==='guild')guildPanel();else if(p==='board')boardPanel();else if(p==='bank')bankPanel()}
function pickpocket(name){let chance=Math.max(.12,Math.min(.78,.28+game.skills.shadow*.12+(game.trust[name]>40?.08:0)));if(Math.random()<chance){let purse=8+Math.floor(Math.random()*17);game.gold+=purse;changeTrust(name,-25);game.rep-=3;addLog(`You lift ${purse} crowns from ${name} without being noticed.`);toast(`A quiet ${purse}-crown score.`)}else{changeTrust(name,-35);game.rep-=8;game.wanted+=20;game.health=Math.max(1,game.health-5);addLog(`${name} catches your hand. The watch will hear of this.`);toast('Caught! Your bounty rises by 20 crowns.')}advance(5);render();speakTo(name)}
function handleExtra(d,b){let n=b.dataset.name;if(d==='chat'){changeTrust(n,4);advance(5);addLog(`You share a few words with ${n}. Trust grows.`);render();speakTo(n)}else if(d==='offer'){game.gold-=5;changeTrust(n,10);advance(10);addLog(`You buy ${n} a drink. The conversation warms.`);render();speakTo(n)}else if(d==='pickpocket')pickpocket(n);else if(d==='tamsin'){let q=game.quests.find(q=>q.title==='A Quiet Disappearance');changeTrust(n,6);if(game.flags.merritLead){finishQuest('A Quiet Disappearance',85,120,4);game.flags.merritLead=false}else if(q){q.progress='Ask Merrit at the Salt Quay';addLog('Tamsin says her brother carried a bundle toward the river. Ask Merrit what he saw.')}advance(5);render();speakTo(n)}else if(d==='merrit'){let q=game.quests.find(q=>q.title==='A Quiet Disappearance');if(q&&!q.done){game.flags.merritLead=true;q.progress='Return to Tamsin with Merrit’s account';changeTrust(n,6);addLog('Merrit remembers Tamsin’s brother boarding a southbound barge. Return to Tamsin.')}else addLog('Merrit has no new news today.');advance(5);render();speakTo(n)}else if(d==='talent'){let t=b.dataset.talent;if((game.flags.talentPoints||0)>0&&game.skills[t]!==undefined){game.skills[t]++;game.flags.talentPoints--;toast(`${t[0].toUpperCase()+t.slice(1)} improved.`);render();actPanel('character')}}}
function init(){document.head.insertAdjacentHTML('beforeend',`<style>.choice-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:13px 0;border-bottom:1px solid #34392f}.choice-row:last-child{border-bottom:0}.choice-row b{font:16px Georgia,serif;color:#e3d8bd}.choice-row small,.modal-note{display:block;color:#9b9b84;font-size:11px;line-height:1.55;margin-top:5px}.choice-btn{border:1px solid #66563a;background:#201f18;color:#e1c38a;padding:9px 12px;white-space:nowrap}.choice-btn:hover:not(:disabled){background:#30291c}.choice-btn:disabled{opacity:.42;cursor:not-allowed}.modal-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.modal-actions .danger{color:#d79583;border-color:#714c40}.map-choices{display:flex;flex-wrap:wrap;gap:8px}.combat-card{padding:10px 0}.combat-card .trust-track{height:8px;background:#30251f;margin:10px 0}.combat-card .trust-fill{display:block;height:100%;background:#a65845}.modal{max-height:88vh;overflow:auto}.touch-controls{touch-action:manipulation}</style>`);render();$('#menu-open').onclick=openMenu;$('#modal-close').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.panel){$$('.navbtn').forEach(x=>x.classList.toggle('active',x===b));actPanel(b.dataset.panel)}if(b.dataset.move)move(b.dataset.move);if(b.dataset.action)doAction(b.dataset.action);if(b.dataset.do){if(['chat','offer','pickpocket','tamsin','merrit','talent'].includes(b.dataset.do))handleExtra(b.dataset.do,b);else handleDo(b)}if(b.id==='clear-log'){game.log=[];renderLog();saveAuto()}});$$('.navbtn').forEach(b=>b.setAttribute('aria-label',`Open ${b.textContent.trim()}`))}
init();

